function LinkCol({ title, links }) {
  return (
    <div>
      <p style={{ fontWeight: 700, fontSize: 20, color: 'var(--paper)', margin: 0, marginBottom: 16, lineHeight: 1.2 }}>
        {title}
      </p>
      <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: 14 }}>
        {links.map((l) => (
          <li key={l.label}>
            <a
              href={l.href}
              target="_blank"
              rel="noopener noreferrer"
              className="footer-link"
              style={{ fontWeight: 400, fontSize: 16, color: 'var(--paper)', textDecoration: 'none', opacity: 0.8, display: 'inline-block' }}
            >
              {l.label}
            </a>
          </li>
        ))}
      </ul>
    </div>
  )
}

